import { useMemo, useState } from "react";
import { ArrowUpRight, Shuffle } from "lucide-react";

const CATEGORY = {
  CASE_STUDY: "Case Study",
  WEB: "Web",
  MOBILE_APP: "Mobile App",
} as const;

type Category = "All" | (typeof CATEGORY)[keyof typeof CATEGORY];

type Project = {
  id: number;
  title: string;
  category: Exclude<Category, "All">;
  image: string;
  description: string;
  link: string;
};

const projects: Project[] = [
  {
    id: 1,
    title: "AI Hiring Platform",
    category: CATEGORY.WEB,
    image: "/landing page copy.png",
    description:
      "AI-powered hiring experience across onboarding, profile enrichment and interview preparation.",
    link: "https://www.figma.com/design/uCCI3aLXDFuIWuUTV77e2k/portolfio?node-id=12-13565&p=f&t=XVIuih7DG3dpy79j-0",
  },
  {
    id: 2,
    title: "Fintech App",
    category: CATEGORY.MOBILE_APP,
    image: "/finura copy.png",
    description:
      "A fintech experience focused on payments, financial workflows and a clear mobile experience.",
    link: "https://www.figma.com/design/uCCI3aLXDFuIWuUTV77e2k/portolfio?node-id=28-5244&p=f&t=XVIuih7DG3dpy79j-0",
  },
  {
    id: 3,
    title: "Food Safety Management",
    category: CATEGORY.WEB,
    image: "/foods copy.png",
    description:
      "A monitoring dashboard designed to simplify complex food-safety operations and decision-making.",
    link: "https://www.figma.com/design/QoRUE76kIbsfC1Cg25Hl1X/Food-safety-dashboard?node-id=0-1&t=ati9AM8mgZaJfQKz-0",
  },
  {
    id: 4,
    title: "Fashion Website",
    category: CATEGORY.WEB,
    image: "/Skincare.png",
    description:
      "A focused commerce experience designed across desktop and mobile.",
    link: "https://www.figma.com/design/uCCI3aLXDFuIWuUTV77e2k/portolfio?node-id=12-10682&t=XVIuih7DG3dpy79j-0",
  },
  {
    id: 5,
    title: "EduHire Case Study",
    category: CATEGORY.CASE_STUDY,
    image: "/Edu.png",
    description:
      "A product experience focused on improving the hiring and candidate evaluation journey.",
    link: "https://www.figma.com/design/uCCI3aLXDFuIWuUTV77e2k/portolfio?node-id=12-10337&t=XVIuih7DG3dpy79j-0",
  },
  {
    id: 6,
    title: "Skincare Website",
    category: CATEGORY.WEB,
    image: "/Skincare.png",
    description:
      "A clean commerce experience with a flexible interface and strong visual hierarchy.",
    link: "https://www.figma.com/design/uCCI3aLXDFuIWuUTV77e2k/portolfio?node-id=12-10337&t=XVIuih7DG3dpy79j-0",
  },
  {
    id: 7,
    title: "Text To Speak",
    category: CATEGORY.CASE_STUDY,
    image: "/Text.png",
    description:
      "An accessible product experience built around text-to-speech interactions.",
    link: "https://www.figma.com/design/uCCI3aLXDFuIWuUTV77e2k/portolfio?node-id=1-345&t=XVIuih7DG3dpy79j-0",
  },
  {
    id: 8,
    title: "Jewelry App",
    category: CATEGORY.MOBILE_APP,
    image: "/Lumera.png",
    description:
      "A mobile shopping experience designed around product discovery and exploration.",
    link: "https://www.figma.com/design/uCCI3aLXDFuIWuUTV77e2k/portolfio?node-id=1-8932&t=N3z4uixgYTIuSshB-0",
  },
];

const categories: Category[] = [
  "All",
  CATEGORY.CASE_STUDY,
  CATEGORY.WEB,
  CATEGORY.MOBILE_APP,
];

function ProjectCard({ project }: { project: Project }) {
  return (
    <a
      href={project.link}
      target="_blank"
      rel="noopener noreferrer"
      className="group block"
    >
      <article className="overflow-hidden rounded-2xl border border-black/[0.08] bg-white transition-all duration-500 hover:-translate-y-1 hover:shadow-[0_20px_60px_rgba(0,0,0,0.08)] dark:border-white/[0.08] dark:bg-[#191919] dark:hover:shadow-[0_20px_60px_rgba(0,0,0,0.25)]">

        {/* Image */}
        <div className="overflow-hidden bg-[#eceae6] p-3 dark:bg-[#222222]">
          <div className="relative aspect-[16/10] overflow-hidden rounded-xl border border-black/[0.06] bg-[#f7f7f7] dark:border-white/[0.06] dark:bg-[#151515]">
            <img
              src={project.image}
              alt={project.title}
              className="h-full w-full object-cover transition-transform duration-700 ease-out group-hover:scale-[1.035]"
            />

            {/* Hover Arrow */}
            <div className="absolute right-4 top-4 flex h-10 w-10 items-center justify-center rounded-full bg-white/90 text-neutral-950 opacity-0 shadow-sm backdrop-blur transition-all duration-300 group-hover:opacity-100 dark:bg-black/80 dark:text-white">
              <ArrowUpRight
                size={17}
                strokeWidth={1.5}
              />
            </div>
          </div>
        </div>

        {/* Information */}
        <div className="p-6 sm:p-7">

          <div className="flex items-center justify-between">
            <span className="text-xs tracking-[0.12em] text-neutral-400">
              {String(project.id).padStart(2, "0")}
            </span>

            <span className="text-xs text-neutral-400">
              {project.category}
            </span>
          </div>

          <h2 className="mt-7 font-serif text-3xl tracking-[-0.03em] sm:text-4xl">
            {project.title}
          </h2>

          <p className="mt-3 max-w-md text-sm leading-6 text-neutral-500 dark:text-neutral-400 sm:text-base">
            {project.description}
          </p>

          <div className="mt-7 flex items-center justify-between border-t border-black/[0.07] pt-5 dark:border-white/[0.08]">
            <span className="text-sm text-neutral-400 transition-colors group-hover:text-neutral-950 dark:group-hover:text-white">
              View project
            </span>

            <ArrowUpRight
              size={18}
              strokeWidth={1.5}
              className="text-neutral-400 transition-all duration-300 group-hover:-translate-y-1 group-hover:translate-x-1 group-hover:text-neutral-950 dark:group-hover:text-white"
            />
          </div>

        </div>
      </article>
    </a>
  );
}

export default function WorkPage() {
  const [activeCategory, setActiveCategory] =
    useState<Category>("All");

  const [shuffled, setShuffled] = useState(false);

  const filteredProjects = useMemo(() => {
    const filtered =
      activeCategory === "All"
        ? [...projects]
        : projects.filter(
            (project) => project.category === activeCategory
          );

    if (!shuffled) {
      return filtered;
    }

    return [...filtered].sort(() => Math.random() - 0.5);
  }, [activeCategory, shuffled]);

  function handleShuffle() {
    setShuffled((value) => !value);
  }

  return (
    <main className="min-h-screen bg-[#f7f5f2] text-neutral-950 transition-colors duration-300 dark:bg-[#111111] dark:text-white">

      <div className="mx-auto min-h-screen max-w-[1200px] border-x border-black/[0.08] dark:border-white/[0.08]">

        {/* Header */}
        <section className="px-6 pb-16 pt-24 sm:px-10 sm:pt-32 lg:px-16">

          <p className="text-sm uppercase tracking-[0.18em] text-neutral-400">
            Work
          </p>

          <div className="mt-7 flex flex-col justify-between gap-8 lg:flex-row lg:items-end">

            <div>
              <h1 className="max-w-3xl font-serif text-5xl leading-[0.95] tracking-[-0.04em] sm:text-7xl">
                All the things
                <br />
                I&apos;ve worked on.
              </h1>

              <p className="mt-8 max-w-xl text-lg leading-8 text-neutral-500 dark:text-neutral-400">
                A collection of product, UX/UI and visual design
                work across different industries and platforms.
              </p>
            </div>

            {/* Shuffle */}
            <button
              type="button"
              onClick={handleShuffle}
              className="group flex w-fit items-center gap-2 text-sm text-neutral-500 transition-colors hover:text-neutral-950 dark:hover:text-white"
            >
              <span>Shuffle</span>

              <Shuffle
                size={17}
                strokeWidth={1.5}
                className="transition-transform duration-500 group-hover:rotate-180"
              />
            </button>

          </div>
        </section>


        {/* Filters */}
        <section className="border-y border-black/[0.08] px-6 py-5 dark:border-white/[0.08] sm:px-10 lg:px-16">

          <div className="flex flex-wrap items-center gap-x-8 gap-y-4">

            {categories.map((category) => {
              const active = activeCategory === category;

              return (
                <button
                  key={category}
                  type="button"
                  onClick={() => {
                    setActiveCategory(category);
                    setShuffled(false);
                  }}
                  className={`text-sm transition-colors duration-200 ${
                    active
                      ? "font-medium text-neutral-950 dark:text-white"
                      : "text-neutral-400 hover:text-neutral-950 dark:hover:text-white"
                  }`}
                >
                  {category}
                </button>
              );
            })}

          </div>
        </section>


        {/* Project Grid */}
        <section className="px-4 py-8 sm:px-6 sm:py-10 lg:px-8">

          {filteredProjects.length > 0 ? (
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">

              {filteredProjects.map((project) => (
                <ProjectCard
                  key={project.id}
                  project={project}
                />
              ))}

            </div>
          ) : (
            <div className="border border-black/[0.08] py-24 text-center text-sm text-neutral-400 dark:border-white/[0.08]">
              No projects in this category yet.
            </div>
          )}

        </section>


        {/* Bottom */}
        <section className="border-t border-black/[0.08] px-6 py-24 dark:border-white/[0.08] sm:px-10 lg:px-16 lg:py-32">

          <p className="max-w-2xl font-serif text-3xl leading-tight tracking-[-0.03em] sm:text-4xl">
            Good design is less about decoration
            and more about making complex things
            easier to understand.
          </p>

        </section>

      </div>
    </main>
  );
}
